-- data_033_of_120.sql: intelligence dataset 2026-09-29, part 33 of 120. Run in order; safe to re-run.

insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--burnley', 'Burnley Football Club', 'Burnley', 'football', 'Premier League', 'England', 'Burnley', 'Turf Moor', 21944, 'https://en.wikipedia.org/wiki/Turf_Moor', 1882, 'burnleyfootballclub.com', 'private_equity', 'Controlled since December 2020 by Velocity Sports Partners, the sports investment arm of US firm ALK Capital (wholly owned by Alan Pace, Mike Smith and Stuart Hunt), which holds 84% of the club; the remaining 16% sits with individual minority shareholders including JJ and Kealia Watt and Malcolm Jenkins. In November 2025 ALK Capital took upwards of $200m from private equity fund Cynosure | Checketts Sports Capital.', 'https://alkcapital.com/2023/09/alk-capital-completes-investment-in-burnley-fc/', 71700000, 'GBP', '2024-25', 'The Swiss Ramble (Burnley FC Holdings Limited accounts 2024/25)', 'https://swissramble.substack.com/p/burnley-finances-202425', null, null, null, null, null, null, '2026-09-28', 'https://linktr.ee/burnleyfc', '[{"platform": "Instagram", "followers": 844000, "as_of": "2026-09-28", "source_url": "https://www.instagram.com/burnleyofficial/"}, {"platform": "X", "followers": 861700, "as_of": "2026-09-28", "source_url": "https://x.com/BurnleyOfficial"}, {"platform": "TikTok", "followers": 1200000, "as_of": "2026-09-28", "source_url": "https://www.tiktok.com/@burnleyofficial?lang=en"}, {"platform": "Facebook", "followers": 1204553, "as_of": "2026-09-28", "source_url": "https://www.facebook.com/burnleyofficial/"}]'::jsonb, 'Takeover price is disputed: Sportico and Fortune report about £170m; GiveMeSport reports £150m. Valuation left null because no Forbes or Sportico page in the results states a Burnley figure; GiveMeSport''s 2025-26 ranking puts Burnley at £200-220m (lowest in the Premier League) citing a blend of Forbes/Sportico/Football Benchmark estimates. Burnley is not in the Deloitte Money League top 20; revenue is from the club''s own 2024/25 accounts (Championship season, £71.7m, £28.5m post-tax loss). Accounts show bank borrowings of £105.3m at 7.25-12% secured on Turf Moor and group assets, with £40m reclassified as long-term after a post-year-end renegotiation; theesk.org flags a going-concern note. The Cynosure | Checketts $200m is at the ALK Capital parent level, not a direct club stake, and Bloomberg framed it as a stake sale bringing a new US investor into the Premier League. ALK also bought 99.66% of RCD Espanyol in October 2025 for a reported €130m, so Burnley is now part of a multi-club group. Social total is not stated by any single source, so the per-platform counts are listed separately.', '["https://alkcapital.com/2023/09/alk-capital-completes-investment-in-burnley-fc/", "https://burnleyfootballclub.com/legal-information/legal-information-company-details", "https://www.premierleague.com/en/news/1961150", "https://www.sportico.com/business/sales/2021/alk-capital-burnley-debt-1234621513/", "https://www.fortune.com/2021/02/06/burnley-alk-capital-private-equity-premier-league-leveraged-buyout", "https://frontofficesports.com/jj-watt-kealia-watt-invest-in-burnley-fc-english-premier-league/", "https://www.neworleanssaints.com/news/new-orleans-saints-safety-malcolm-jenkins-becomes-minority-investor-in-burnley-f", "https://alkcapital.com/2025/11/alk-capital-and-cynosure-checketts-sports-capital-reunite-in-significant-strategic-investment-across-european-football/", "https://www.bloomberg.com/news/articles/2025-11-03/premier-league-gets-new-us-investor-after-burnley-fc-stake-sale", "https://www.sportspro.com/news/espanyol-takeover-alk-capital-velocity-sport-burnley-laliga-july-2025/", "https://swissramble.substack.com/p/burnley-finances-202425", "https://theesk.org/2026/05/07/the-analysis-series-burnley-fc-holdings-limited-annual-report-and-financial-statements-2024-25/", "https://www.burnleyfootballclub.com/club-accounts", "https://www.givemesport.com/premier-league-every-club-ranked-most-least-valuable/", "https://en.wikipedia.org/wiki/Turf_Moor", "https://en.wikipedia.org/wiki/Burnley_F.C.", "https://www.instagram.com/burnleyofficial/", "https://x.com/BurnleyOfficial", "https://www.tiktok.com/@burnleyofficial?lang=en", "https://www.facebook.com/burnleyofficial/", "https://linktr.ee/burnleyfc"]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;
